const b = $json.body || $json;

function s(v){ return (v ?? '').toString().trim(); }

const payload = {
  goal: s(b.goal),
  deadline: s(b.deadline || '30 days'),
  bizType: s(b.bizType || 'Other'),
  teamSize: s(b.teamSize || '6-15'),
  context: s(b.context),
  pain: s(b.pain),
  tried: s(b.tried),
  page: s(b.page || 'business-coach-genie'),
};

// Basic validation
if (!payload.goal && !payload.context && !payload.pain) {
  return [{
    ok: false,
    error: "Please provide at least a Goal, Situation, or Pain Point.",
    payload
  }];
}

return [{ ok: true, payload }];

