const text = $json?.choices?.[0]?.message?.content || $json?.data?.[0]?.message?.content || $json?.message?.content || $json?.response || '';

// Lightweight parsing helpers (optional)
const lines = (text || '').split('\n').map(l => l.trim()).filter(Boolean);

// Attempt to extract a "Next 7 steps" block
let nextSteps = [];
let inNext = false;
for (const l of lines) {
  const low = l.toLowerCase();
  if (low.includes('next 7') && low.includes('step')) { inNext = true; continue; }
  if (inNext && (low.startsWith('5)') || low.startsWith('scripts') || low.includes('templates'))) { inNext = false; }
  if (inNext) {
    const cleaned = l.replace(/^[-*\d+.\)]\s*/, '').trim();
    if (cleaned) nextSteps.push(cleaned);
  }
}
nextSteps = nextSteps.slice(0, 7);

return [{
  ok: true,
  result: text,
  next_steps: nextSteps,
  meta: {
    model: $json?.model || 'unknown',
    usage: $json?.usage || null
  }
}];
